<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte de cambios del plan</title><style>@page{margin:28px}body{font-family:DejaVu Sans,sans-serif;color:#243b35;font-size:10px;line-height:1.4}h1{color:#175b46;font-size:20px}h2{color:#175b46;font-size:13px;border-bottom:1px solid #b9d4ca;padding-bottom:4px;margin-top:18px}.box{background:#f1f7f5;border:1px solid #d6e5df;padding:9px;margin:6px 0}.grid{width:100%;border-collapse:collapse}.grid th,.grid td{border:1px solid #d5dfdc;padding:5px}.grid th{background:#e6f0ec;text-align:left}.tag{display:inline-block;background:#e6f0ec;padding:2px 6px;margin:2px;border-radius:8px}.muted{color:#687d76}ul{padding-left:17px}</style></head><body>
