<h1>Reporte de cambios del plan alimentario</h1><p class="muted">Generado {{ $fechaGeneracion->format('d/m/Y H:i') }} por {{ $profesional->name }}</p>
<h2>Paciente y planes comparados</h2><table class="grid"><tr><th>Paciente</th><th>Plan anterior</th><th>Plan nuevo</th></tr><tr><td>{{ $nombre }}</td><td>{{ $planAnterior?->nombre ?? 'Sin plan anterior' }}</td><td>{{ $planNuevo->nombre }}</td></tr></table>
