<h2>Alertas, síntomas y seguimiento</h2><p>@forelse($reporte['alertas_consideradas'] as $a)<span class="tag">{{ $a }}</span>@empty Sin alertas automáticas relevantes. @endforelse</p><p><b>Adherencia del plan anterior:</b> {{ $reporte['adherencia_plan_anterior']===null?'Sin registro':$reporte['adherencia_plan_anterior'].'%' }}</p>
<h2>Fuentes consideradas</h2><ul>@foreach($reporte['datos_considerados'] as $d)<li>{{ $d }}</li>@endforeach</ul>
